function __agentaProviderCost(usage, rawUsage) {
    // Agenta build patch (services/runner/src/tools/pi-provider-cost-patch.ts): keep the charge
    // the provider billed (OpenRouter usage.cost) instead of Pi's price-table estimate.
    const billed = rawUsage ? rawUsage.cost : undefined;
    if (typeof billed !== "number" || !Number.isFinite(billed) || billed < 0)
        return;
    const estimated = usage.cost.total;
    if (estimated > 0) {
        const scale = billed / estimated;
        usage.cost.input *= scale;
        usage.cost.output *= scale;
        usage.cost.cacheRead *= scale;
        usage.cost.cacheWrite *= scale;
    }
    usage.cost.total = billed;
    usage.cost.source = "provider";
}
